import{_ as i,o as t,c as a,a8 as l}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"Rule Description","description":"","frontmatter":{"title":"Rule Description","lang":"en"},"headers":[],"relativePath":"advance/rule.md","filePath":"advance/rule.md","lastUpdated":1790353258000}'),s={name:"advance/rule.md"};function r(o,e,n,c,d,h){return t(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJSdWxlJTIwRGVzY3JpcHRpb24lMjIlMkMlMjJsYW5nJTIyJTNBJTIyZW4lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1MzI1ODAwMCU3RA=="},[...e[0]||(e[0]=[l('<h1 id="rule-description" tabindex="-1">Rule Description <a class="header-anchor" href="#rule-description" aria-label="Permalink to &quot;Rule Description&quot;">​</a></h1><p>This module uses the following configuration files, all of which must be in the same directory and to which nginx has read access.</p><ul><li>IP whitelist with the file names <code>white-ipv4</code> and <code>white-ipv6</code>.</li><li>IP blacklist with the filenames <code>ipv4</code> and <code>ipv6</code>.</li><li>Url whitelist with the filename <code>white-url</code>.</li><li>Url blacklist with the filename <code>url</code>.</li><li>Get parameter blacklist with the filename <code>args</code>.</li><li>Post request body blacklist, with the filename <code>post</code>.</li><li>UserAgent blacklist with the filename <code>user-agent</code>.</li><li>Cookie blacklist, with the filename <code>cookie</code>.</li><li>Referer whitelist with the filename <code>white-referer</code>.</li><li>Referer blacklist with the filename <code>referer</code>.</li><li>Advanced rules with the file name <code>advaced</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>Some rule files require writing regular expressions, one regular expression per line. Regular expressions follow the <a href="http://www.pcre.org/current/doc/html/pcre2syntax.html" target="_blank" rel="noreferrer">PCRE standard</a>.</p></div><h2 id="ip-whitelist" tabindex="-1">IP Whitelist <a class="header-anchor" href="#ip-whitelist" aria-label="Permalink to &quot;IP Whitelist&quot;">​</a></h2><p>The ip whitelist consists of the following two files.</p><ul><li>ipv4 whitelist with the file name <code>white-ipv4</code>.</li><li>ipv6 whitelist with the file name <code>white-ipv6</code>.</li></ul><p>Specify one IP address or IP address range per line when writing.</p><p>Here are some examples.</p><p>Specifies a single ipv4 address.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.2.1</span></span></code></pre></div><p>Specifies an ipv4 address range.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.2.0/24</span></span></code></pre></div><p>Specifies a single ipv6 address.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FE80::1000</span></span></code></pre></div><p>Specifies an ipv6 address range.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FE80::/10</span></span></code></pre></div><h2 id="ip-blacklist" tabindex="-1">IP Blacklist <a class="header-anchor" href="#ip-blacklist" aria-label="Permalink to &quot;IP Blacklist&quot;">​</a></h2><p>The IP blacklist consists of the following two files.</p><ul><li>ipv4 blacklist with the file name <code>ipv4</code>.</li><li>ipv6 blacklist with the file name <code>ipv6</code>.</li></ul><p>Write the same as <a href="#ip-whitelist">IP Whitelist</a>.</p><h2 id="url-whitelist" tabindex="-1">Url Whitelist <a class="header-anchor" href="#url-whitelist" aria-label="Permalink to &quot;Url Whitelist&quot;">​</a></h2><p>The Url whitelist file name is <code>white-url</code>, and the rule is written with one regular expression per line. Url matched by any of the regular expressions will be released directly without subsequent checks.</p><h2 id="url-blacklist" tabindex="-1">Url Blacklist <a class="header-anchor" href="#url-blacklist" aria-label="Permalink to &quot;Url Blacklist&quot;">​</a></h2><p>The Url blacklist file name is <code>url</code>, and the rule is written with one regular expression per line. Url will be blocked if it is matched by any of the regular expressions, and a 403 status code will be returned.</p><h2 id="get-parameter-blacklist" tabindex="-1">Get Parameter Blacklist <a class="header-anchor" href="#get-parameter-blacklist" aria-label="Permalink to &quot;Get Parameter Blacklist&quot;">​</a></h2><p>The Get parameter is blacklisted with the file name <code>args</code>, and the rule is written with one regular expression per line. If the Get parameter is matched by any of the regular expressions, it will be intercepted and a 403 status code will be returned.</p><h2 id="post-body-blacklist" tabindex="-1">Post body Blacklist <a class="header-anchor" href="#post-body-blacklist" aria-label="Permalink to &quot;Post body Blacklist&quot;">​</a></h2><p>The file name of the Post body blacklist is <code>post</code>, and the rule is written with one regular expression per line. The content of the Post body will be blocked if any of the regular expressions match it, and a 403 status code will be returned.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Sometimes this module does not perform Post body inspection, see <a href="/ngx_waf-docs/guide/faq.html#post-inspection-failure">FAQ</a> for details.</p></div><h2 id="user-agent-blacklist" tabindex="-1">User-Agent Blacklist <a class="header-anchor" href="#user-agent-blacklist" aria-label="Permalink to &quot;User-Agent Blacklist&quot;">​</a></h2><p>The file name of the UserAgent blacklist is <code>user-agent</code>, and the rule is written with one regular expression per line. UserAgent will be blocked if any of the regular expressions match it, and a 403 status code will be returned.</p><h2 id="cookie-blacklist" tabindex="-1">Cookie Blacklist <a class="header-anchor" href="#cookie-blacklist" aria-label="Permalink to &quot;Cookie Blacklist&quot;">​</a></h2><p>The file name of the cookie blacklist is <code>cookie</code> and the rule is written with one regular expression per line. If a cookie is matched by any of the regular expressions, it will be blocked and a 403 status code will be returned.</p><h2 id="referer-whitelist" tabindex="-1">Referer Whitelist <a class="header-anchor" href="#referer-whitelist" aria-label="Permalink to &quot;Referer Whitelist&quot;">​</a></h2><p>The referer whitelist is named <code>white-referer</code>, and the rule is written with one regular expression per line. The referer will be released if it is matched by any of the regular expressions, and no subsequent checks will be performed.</p><h2 id="referer-blacklist" tabindex="-1">Referer Blacklist <a class="header-anchor" href="#referer-blacklist" aria-label="Permalink to &quot;Referer Blacklist&quot;">​</a></h2><p>The Referer blacklist file is named <code>referer</code> and the rule is written with one regular expression per line. Referer will be blocked if it is matched by any of the regular expressions, and a 403 status code will be returned.</p>',38)])])}const b=i(s,[["render",r]]);export{u as __pageData,b as default};
